            consequences = listOf("Развитие скрытого пожара.", "Потеря времени при ошибочном признании сигнала ложным."),
            related = listOf("smoke-fire-flashover", "motor-fan-failure", "transformer-protection", "protection-trip")
        )
    )

    private fun expandedScenario(
        id: String,
        category: String,
        title: String,
        summary: String,
        severity: DiagnosticSeverity,
        immediate: List<String>,
        danger: List<String>,
        questions: List<DiagnosticQuestion>,
        causes: List<String>,
        checks: List<DiagnosticCheck>,
        equipment: List<String>,
        explanation: List<String>,
        consequences: List<String>,
        related: List<String>
    ) = DiagnosticScenario(
        id = id,
        category = category,
        title = title,
        summary = summary,
        immediateActions = immediate,
        dangerSigns = danger,
        questions = questions,
        probableCauses = causes,
        checks = checks,
        prohibited = listOf(
            "Шунтировать защиту, блокировку или удерживать аппарат вручную.",
            "Создавать аварийный режим повторно только ради уточнения причины.",
            "Выполнять работы вне своего допуска или местной инструкции."
        ),
        stopConditions = danger + "Причина не установлена, а безопасная работа системы не подтверждена.",
        reportFields = listOf("секция и зона", "режим, скорость и позиция", "показания приборов", "сигнальные лампы/защита", "что произошло первым", "результаты безопасных проверок"),
        relatedEquipment = equipment,
        sourceNote = "Руководство по эксплуатации ВЛ80С, разделы устройства, электрических/пневматических схем и характерных неисправностей; действующие ПТЭ, правила тормозов и охраны труда. Точные обозначения и действия сверять по документации конкретной секции.",
        severity = severity,
        observableSigns = listOf(summary) + danger,
        systemExplanation = explanation,
        operationalConsequences = consequences,
        trainingNotes = listOf(
            "Сначала отделяйте отсутствие команды от отсутствия исполнения команды.",
            "Сравнение секций полезно только при одинаковых условиях и достоверной индикации.",
            "Первичный признак важнее конечного: несколько отказов могут закончиться одинаковым отключением."
        ),
        feedbackPrompts = listOf("Что изменилось после безопасного действия?", "Какая секция отличается от остальных?", "Что произошло первым по времени?", "Какие показания удалось записать?"),
        relatedScenarioIds = related
    )

    private fun branchQuestion(
        key: String,
        text: String,
        yes: String,
        no: String,
        yesNext: String,
        noNext: String
    ) = DiagnosticQuestion(text, yes, no, key, yesNext, noNext)

    private fun cabCheck(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.CAB)

    private fun stopCheck(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.SAFE_STOP)

    private fun authorizedCheck(title: String, action: String, expected: String, abnormal: String) =
        DiagnosticCheck(title, action, expected, abnormal, DiagnosticActionLevel.AUTHORIZED_ONLY)
}
